    let html = await get(path + query);
    check(html);
    assert.match(html, /Complete First/);
    assert.doesNotMatch(html, /Complete Second|Complete Third/);
    html = await post(path + '/tasks/1/rename', { ...selected, title: ' Renamed ' });
    check(html);
